#include <pthread.h>
#include <stdio.h>
#include <unistd.h>

pthread_mutex_t shared_mutex = PTHREAD_MUTEX_INITIALIZER;

// The clean-up handler function. It must take one void* argument.
void cleanup_routine(void *arg) {
    pthread_mutex_t *m = (pthread_mutex_t *)arg;
    printf("Cleanup Handler: Executing routine to unlock mutex.\n");
    // Unlock the mutex passed as 'arg'
    pthread_mutex_unlock(m);
}

void* worker_thread(void *arg) {
    printf("Worker: Attempting to lock mutex.\n");
    if (pthread_mutex_lock(&shared_mutex) != 0) {
        perror("pthread_mutex_lock");
        return NULL;
    }
    printf("Worker: Mutex locked. Pushing cleanup handler.\n");

    // Must be paired with a pop within the same block scope
    {
        pthread_cleanup_push(cleanup_routine, &shared_mutex);

        // Simulate doing work (e.g., waiting for I/O)
        printf("Worker: Critical section work started. (If canceled now, cleanup runs).\n");
        sleep(1);

        // Clean-up pop(1) executes the handler immediately
        printf("Worker: Work done. Popping and executing handler.\n");
        pthread_cleanup_pop(1); 
    }

    printf("Worker: Exiting thread normally.\n
");
    return NULL;
}

int main() {
    pthread_t tid;

    if (pthread_create(&tid, NULL, worker_thread, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    pthread_join(tid, NULL);

    // Verify that the worker thread successfully unlocked the mutex via the handler
    if (pthread_mutex_trylock(&shared_mutex) == 0) {
        printf("Main: Mutex available, cleanup successful.\n");
        pthread_mutex_unlock(&shared_mutex);
    } else {
        fprintf(stderr, "Main: ERROR: Mutex remained locked!\n");
        return 1;
    }

    pthread_mutex_destroy(&shared_mutex);
    return 0;
}
